// Builds lib/guesses.ts from the ENABLE word list.
// Run it with:  node scripts/build-guesses.mjs
//
// Why a script instead of pasting the words in by hand: it records exactly where
// the list came from and how it was filtered, and it can be re-run any time.
// The game itself never downloads anything; it just imports the generated file.
//
// ENABLE ("Enhanced North American Benchmark LExicon") is a public-domain word
// list made for word games.

import { writeFileSync } from "node:fs";

const SOURCE_URL = "https://raw.githubusercontent.com/dolph/dictionary/master/enable1.txt";
const OUTPUT_FILE = new URL("../lib/guesses.ts", import.meta.url);
const WORDS_PER_LINE = 13;

const response = await fetch(SOURCE_URL);
if (!response.ok) throw new Error(`Download failed: ${response.status}`);
const text = await response.text();

// Keep only words that are exactly 5 lowercase letters (a-z). The regex also
// throws out anything weird in the file, like stray characters or blank lines.
const words = text
  .split(/\r?\n/)
  .map((word) => word.trim().toLowerCase())
  .filter((word) => /^[a-z]{5}$/.test(word));

// Same space-separated format as lib/words.ts, a few words per line.
const lines = [];
for (let i = 0; i < words.length; i += WORDS_PER_LINE) {
  lines.push(words.slice(i, i + WORDS_PER_LINE).join(" "));
}

const output = `// GENERATED by scripts/build-guesses.mjs - don't edit by hand, re-run the script.
// Every 5-letter word from the ENABLE word list (public domain), ${words.length} words.

export const ALLOWED_GUESSES: string[] = \`
${lines.join("\n")}
\`.trim().split(/\\s+/);
`;

writeFileSync(OUTPUT_FILE, output);
console.log(`Wrote ${words.length} words to lib/guesses.ts`);
